<script setup lang="ts">
import {ref,onMounted} from 'vue'
import AssuranceContactEditor from './AssuranceContactEditor.vue'
import {Upload,Search,ChevronLeft,ChevronRight,FileSpreadsheet,CheckCircle2,X,ArrowLeft,SlidersHorizontal,RefreshCw} from 'lucide-vue-next'
const props=defineProps<{request:(path:string,body?:any,method?:string)=>Promise<any>;role:string;portal:(path:string,body?:any)=>Promise<any>}>()
const emit=defineEmits<{imported:[count:number]}>()
const rows=ref<any[]>([]),count=ref(0),page=ref(1),search=ref(''),status=ref(''),stages=ref<any[]>([]),loading=ref(false),working=ref(false),error=ref('')
const importing=ref(false),file=ref<File|null>(null),hasHeader=ref(true),preview=ref<any>(null),report=ref<any>(null),history=ref<any[]>([]),historyPage=ref(1),historyCount=ref(0),selected=ref<any>(null)
const mapping=ref<Record<string,string>>({name:'',phone:'',email:''})
const customMapping=ref<Record<string,string>>({})
const filterDialog=ref<HTMLDialogElement|null>(null),draftStatus=ref('')
function openFilters(){draftStatus.value=status.value;filterDialog.value?.showModal()}
function applyFilters(){status.value=draftStatus.value;page.value=1;filterDialog.value?.close();load()}
let requestId=''
async function load(){loading.value=true;try{const data=await props.request(`contacts/?search=${encodeURIComponent(search.value)}&status=${encodeURIComponent(status.value)}&page=${page.value}`);rows.value=data.results;count.value=data.count}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function loadHistory(){const data=await props.request('imports/?page='+historyPage.value);history.value=data.results;historyCount.value=data.count}
async function openImport(){importing.value=true;error.value='';try{await loadHistory()}catch(e:any){error.value=e.message}}
function resetPreview(){customMapping.value={};preview.value=null;report.value=null;requestId='';mapping.value={name:'',phone:'',email:''}}
function choose(event:Event){file.value=(event.target as HTMLInputElement).files?.[0]||null;resetPreview()}
async function inspect(){if(!file.value)return;working.value=true;error.value='';resetPreview();try{const body=new FormData();body.append('file',file.value);body.append('has_header',String(hasHeader.value));preview.value=await props.request('imports/',body);customMapping.value=Object.fromEntries(preview.value.custom_schema.fields.map((f:any)=>[f.key,'']));requestId=crypto.randomUUID()}catch(e:any){error.value=e.message}finally{working.value=false}}
async function confirm(){if(!file.value||!preview.value||mapping.value.phone==='')return;working.value=true;error.value='';try{const body=new FormData();body.append('file',file.value);body.append('has_header',String(hasHeader.value));body.append('mode','confirm');body.append('custom_mapping',JSON.stringify(Object.fromEntries(Object.entries(customMapping.value).filter(([,v])=>v!==''&&v!==undefined).map(([k,v])=>[k,Number(v)]))));body.append('schema_revision',String(preview.value.custom_schema.revision));body.append('request_id',requestId);body.append('mapping',JSON.stringify(Object.fromEntries(Object.entries(mapping.value).filter(([,v])=>v!=='').map(([k,v])=>[k,Number(v)]))));report.value=await props.request('imports/',body);preview.value=null;historyPage.value=1;page.value=1;search.value='';await load();emit('imported',count.value);await loadHistory()}catch(e:any){error.value=e.message}finally{working.value=false}}
function downloadReport(batch:any){const content='\uFEFFLigne;Résultat\r\n'+batch.report.map((row:any)=>`${row.line};${row.reason.replaceAll(';',',')}`).join('\r\n');const url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`rapport-import-${batch.id}.csv`;a.click();URL.revokeObjectURL(url)}
async function inspectContact(row:any){error.value='';try{selected.value=await props.request('contacts/'+row.id+'/')}catch(e:any){error.value=e.message}}
onMounted(async()=>{await load();try{stages.value=(await props.request('pipeline/')).stages}catch(e:any){error.value=e.message}})
</script>
<template>
<div class="assurance-contacts"><p v-if="error" role="alert" class="error">{{error}}</p>
<template v-if="!selected">
 <header class="contact-navigation"><h2>Contacts</h2><span class="active-tab">Liste des contacts</span><button v-if="role==='administrator'" @click="openImport">Imports et historique</button></header>
 <div class="contact-list-tabs"><button :class="{active:!status}" @click="status='';page=1;load()">Tous les contacts</button><span v-if="status" class="filter-chip">{{stages.find(stage=>stage.key===status)?.label||status}}<button aria-label="Retirer le filtre de statut" @click="status='';page=1;load()"><X :size="13"/></button></span></div>
 <div class="contact-actions">
  <button v-if="role==='administrator'" class="primary" @click="openImport"><Upload :size="16"/>Importer</button>
  <button class="secondary" aria-label="Actualiser les contacts" :disabled="loading" @click="load"><RefreshCw :size="16"/></button>
  <form class="contact-search" @submit.prevent="page=1;load()"><Search :size="16"/><input v-model="search" aria-label="Rechercher un contact" placeholder="Nom, téléphone ou e-mail"><button :disabled="loading" aria-label="Lancer la recherche"><ChevronRight :size="16"/></button></form>
  <button class="secondary" @click="openFilters"><SlidersHorizontal :size="16"/>Filtres<span v-if="status" class="filter-count">1</span></button>
 </div>
 <div class="contact-list-summary"><span>{{loading?'Chargement…':'Liste des contacts de votre espace'}}</span><span>{{count}} contacts · Page {{page}} / {{Math.max(1,Math.ceil(count/25))}}</span></div>
</template>
<dialog ref="filterDialog" class="contact-filter-drawer" aria-labelledby="contact-filter-title"><form @submit.prevent="applyFilters"><header><div><h3 id="contact-filter-title">Filtres</h3><p>Affiner la liste des contacts</p></div><button type="button" class="secondary" aria-label="Fermer les filtres" @click="filterDialog?.close()"><X :size="18"/></button></header><label>Statut commercial<select v-model="draftStatus"><option value="">Tous les statuts</option><option v-for="stage in stages" :key="stage.key" :value="stage.key">{{stage.label}}{{stage.active?'':' (archivé)'}}</option></select></label><footer><button type="button" class="secondary" @click="draftStatus=''">Réinitialiser</button><button class="primary">Appliquer</button></footer></form></dialog>
<section v-if="importing" class="import-panel" aria-label="Import des contacts Assurance"><div class="contacts-toolbar"><h3><FileSpreadsheet :size="20"/>Import Assurance</h3><button class="secondary" :disabled="working" @click="importing=false;resetPreview()"><X :size="16"/>Fermer</button></div><p class="subtle">Les valeurs sont conservées telles que lues. Les doublons restent présents. Aucun contrôle téléphonique n’est lancé.</p><div class="import-options"><label>Fichier CSV ou Excel<input type="file" accept=".csv,.xlsx" :disabled="working" @change="choose"></label><label class="checkbox-label"><input v-model="hasHeader" type="checkbox" :disabled="working" @change="resetPreview">La première ligne contient les titres</label><button class="secondary" :disabled="!file||working" @click="inspect">{{working?'Traitement…':'Prévisualiser'}}</button></div><small>5 Mo, 10 000 lignes et 100 colonnes maximum. Excel : première feuille uniquement. Les cellules sont lues, sans reprise de la mise en forme.</small>
<template v-if="preview"><h4>Associer les colonnes · {{preview.total}} ligne(s)</h4><p v-if="preview.sheet" class="subtle">{{preview.sheet}}</p><div class="import-mapping"><label v-for="field in ['phone','name','email']" :key="field">{{({phone:'Téléphone (requis)',name:'Nom',email:'E-mail'} as Record<string,string>)[field]}}<select v-model="mapping[field]" :disabled="working"><option value="">{{field==='phone'?'Choisir une colonne':'Ne pas importer ce champ'}}</option><option v-for="column in preview.columns" :key="column.index" :value="String(column.index)">{{column.index+1}} · {{column.label}}</option></select></label></div><p>Champs métier facultatifs à importer : dès qu’un champ est associé, les obligations de tous les champs actifs s’appliquent. Sans association métier, l’import brut reste inchangé. Booléens : oui/non, true/false ou 1/0 ; dates : AAAA-MM-JJ (cellules Excel date à minuit acceptées). Aucun partage conseiller supplémentaire n’est activé par l’import.</p><div class="import-mapping"><label v-for="field in preview.custom_schema.fields.filter((f:any)=>f.active)" :key="field.key">{{field.label}} · {{field.type}}{{field.required?' · obligatoire':''}}{{field.advisor_visible?' · visible au conseiller':''}}<select v-model="customMapping[field.key]" :disabled="working"><option value="">Ne pas importer ce champ</option><option v-for="column in preview.columns" :key="column.index" :value="String(column.index)">{{column.index+1}} · {{column.label}}</option></select></label></div><div class="table-scroll preview-table"><table><thead><tr><th>Ligne</th><th v-for="column in preview.columns" :key="column.index">{{column.label}}</th></tr></thead><tbody><tr v-for="row in preview.rows" :key="row.line"><td>{{row.line}}</td><td v-for="(value,index) in row.values" :key="index">{{value}}</td></tr></tbody></table></div><p class="subtle">Aperçu des cinq premières lignes. Les lignes sans téléphone ou dont un champ dépasse la taille acceptée seront signalées dans le rapport.</p><button class="primary" :disabled="working||mapping.phone===''" @click="confirm"><CheckCircle2 :size="17"/>Confirmer l’import</button></template>
<div v-if="report" role="status" class="import-result"><h4>Import terminé</h4><p>{{report.imported}} contact(s) importé(s) · {{report.rejected}} ligne(s) rejetée(s) sur {{report.total}}</p><button v-if="report.rejected" class="secondary" @click="downloadReport(report)">Télécharger les lignes à corriger</button><ul v-if="report.rejected"><li v-for="row in report.report.slice(0,10)" :key="row.line">Ligne {{row.line}} : {{row.reason}}</li></ul><small v-if="report.rejected>10">Le rapport téléchargé contient toutes les lignes rejetées.</small></div>
<h4>Historique des imports</h4><p v-if="!history.length" class="subtle">Aucun import enregistré.</p><div v-else class="import-history"><button v-for="batch in history" :key="batch.id" class="history-item" @click="report=batch"><span>{{batch.filename}}<small>{{new Date(batch.created_at).toLocaleString('fr-FR')}}</small></span><span>{{batch.imported}} importé(s) · {{batch.rejected}} rejetée(s)</span></button></div><div v-if="historyCount>20" class="contacts-pagination"><button class="secondary" :disabled="historyPage===1" @click="historyPage--;loadHistory().catch(e=>error=e.message)">Précédent</button><span>Page {{historyPage}}</span><button class="secondary" :disabled="historyPage*20>=historyCount" @click="historyPage++;loadHistory().catch(e=>error=e.message)">Suivant</button></div></section>
<AssuranceContactEditor v-if="selected" :key="selected.id" :contact="selected" :portal="portal" :request="request" :role="role" @close="selected=null" @changed="load"/>
<div v-show="!selected" class="table-scroll"><table><thead><tr><th>Contact</th><th>Téléphone fourni</th><th>E-mail</th><th>Statut</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><button class="crm-contact-link" :disabled="!!selected" @click="inspectContact(row)"><span class="crm-contact-avatar">{{(row.name||'?').slice(0,1).toUpperCase()}}</span><strong>{{row.name||'Sans nom'}}</strong></button></td><td>{{row.phone}}</td><td>{{row.email||'—'}}</td><td><span class="contact-status">{{row.status_label||row.status}}</span></td><td><button class="secondary" :disabled="!!selected" @click="inspectContact(row)">Voir la fiche</button></td></tr><tr v-if="!rows.length"><td colspan="5">{{loading?'Chargement…':'Aucun contact dans votre périmètre.'}}</td></tr></tbody></table></div><div v-show="!selected" class="contacts-pagination"><span>{{count}} contact(s) · page {{page}}</span><button class="secondary" :disabled="loading||page===1" @click="page--;load()"><ChevronLeft :size="16"/>Précédent</button><button class="secondary" :disabled="loading||page*25>=count" @click="page++;load()">Suivant<ChevronRight :size="16"/></button></div>
</div>
</template>
<style scoped>
.assurance-contacts{margin-top:30px}.contacts-toolbar,.contacts-toolbar form,.contacts-pagination{display:flex;align-items:end;gap:12px;flex-wrap:wrap}.contacts-toolbar{justify-content:space-between;margin-bottom:24px}.contacts-toolbar form label{min-width:240px}.contacts-toolbar h3{display:flex;gap:10px;align-items:center;margin:0}.import-panel,.contact-detail{border:1px solid #dfe2ce;border-radius:16px;background:#f8f8f0;padding:24px;margin-bottom:28px}.import-options,.import-mapping{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;align-items:end;margin:24px 0}.checkbox-label{display:flex;align-items:center;gap:8px;font-weight:400}.checkbox-label input{width:auto}.import-panel select{padding:12px;border:1px solid #dedfce;border-radius:10px;background:white;max-width:100%}.preview-table{max-height:300px;margin:20px 0}.preview-table td{min-width:130px;max-width:260px;overflow-wrap:anywhere}.import-result{background:#edf2e1;border-radius:12px;padding:18px;margin:24px 0}.import-result li{margin:8px 0}.import-history{display:grid;gap:8px}.history-item{display:flex;justify-content:space-between;gap:15px;text-align:left;padding:16px;background:#fff;border:1px solid #e1e3d4;border-radius:10px;color:inherit;cursor:pointer}.contacts-pagination{align-items:center;justify-content:end;margin-top:20px}.contacts-pagination>span:first-child{margin-right:auto;color:#7c806d}.contact-status{background:#eef1e3;color:#52642b;border-radius:7px;padding:5px 9px;white-space:nowrap}.contact-detail dl{display:grid;grid-template-columns:150px 1fr;gap:16px}.contact-detail dd{margin:0;white-space:pre-wrap;overflow-wrap:anywhere}.assurance-contacts td{white-space:pre-wrap;overflow-wrap:anywhere}.assurance-contacts button:disabled{opacity:.5;cursor:not-allowed}@media(max-width:750px){.import-options,.import-mapping{grid-template-columns:1fr}.import-panel,.contact-detail{padding:16px}.history-item{flex-direction:column}.contact-detail dl{grid-template-columns:1fr;gap:8px}}
.crm-contact-link{display:flex;align-items:center;gap:10px;border:0;background:none;padding:0;color:#2d4f7b;text-align:left;cursor:pointer}.crm-contact-link strong{font-size:12px;font-weight:600}.crm-contact-avatar{width:32px;height:32px;display:grid;place-items:center;border-radius:50%;background:#eaf1fd;color:#4c7cb7;flex-shrink:0}.crm-contact-link:hover strong{text-decoration:underline}
</style>
<style scoped>
.assurance-contacts{margin:0!important}.contact-navigation{display:flex;align-items:center;gap:28px;background:#fff;padding:0 24px;border-bottom:1px solid #dfe5ed;min-height:64px}.contact-navigation h2{font-size:19px;margin:0;color:#253347}.contact-navigation button{border:0;background:none;color:#596779;cursor:pointer;font-size:13px;padding:23px 0}.active-tab{font-size:13px;color:#1887c8;border-bottom:2px solid #1887c8;align-self:stretch;display:flex;align-items:center}.contact-list-tabs{display:flex;align-items:center;gap:18px;padding:0 24px;min-height:54px;border-bottom:1px solid #e1e8ef;background:#f2f7fa}.contact-list-tabs>button{border:0;background:none;padding:17px 0;cursor:pointer;color:#5d7185;font-size:12px}.contact-list-tabs>button.active{border-bottom:3px solid #2196d3;color:#253347}.contact-actions{display:flex;align-items:center;gap:8px;padding:16px 24px;background:#f2f7fa}.contact-search{margin-left:auto;display:flex!important;align-items:center!important;gap:8px!important;background:white;border:1px solid #dce3ea;border-radius:5px;padding:0 10px;min-width:280px}.contact-search input{border:0!important;padding:9px 0!important;outline-offset:2px;font-size:12px!important;min-width:0}.contact-search button{background:none;border:0;color:#748496;cursor:pointer}.contact-list-summary{display:flex;justify-content:space-between;padding:10px 24px;background:#eaf4fc;color:#6a7b8e;font-size:11px}.filter-chip{display:flex;align-items:center;gap:8px;font-size:12px;color:#2272a6;background:#e4f0fb;border-radius:14px;padding:5px 10px}.filter-chip button{border:0;background:none;display:flex;color:inherit;cursor:pointer}.filter-count{background:#217bd0;color:white;border-radius:50%;padding:1px 5px;font-size:10px}.contact-filter-drawer{position:fixed;inset:0 0 0 auto;margin:0;width:min(370px,100vw);max-width:100vw;height:100dvh;max-height:100dvh;border:0;padding:0;box-shadow:-8px 0 35px #24364e24;color:#29394d}.contact-filter-drawer::backdrop{background:#182b4255}.contact-filter-drawer form{display:flex;flex-direction:column;min-height:100%;gap:24px}.contact-filter-drawer header{display:flex;align-items:center;justify-content:space-between;padding:22px;border-bottom:1px solid #e5ebf1}.contact-filter-drawer h3{margin:0;font-size:17px}.contact-filter-drawer p{font-size:12px;color:#798897;margin:6px 0 0}.contact-filter-drawer label{margin:0 22px;display:grid;gap:10px;font-size:13px}.contact-filter-drawer select{width:100%;padding:12px;border:1px solid #dce3eb;border-radius:5px;background:#f6f8fb}.contact-filter-drawer footer{margin-top:auto;display:flex;justify-content:flex-end;gap:10px;padding:22px;border-top:1px solid #e5ebf1}.contacts-pagination{padding:16px 24px;margin:0;background:white}.assurance-contacts>.table-scroll{border:0;border-radius:0;background:white}.assurance-contacts>.table-scroll td{height:54px;padding:10px 24px!important;font-size:12px}.assurance-contacts>.table-scroll th{padding:12px 24px!important;background:#fff!important;font-size:11px}.assurance-contacts>.table-scroll tr:hover td{background:#f8fbfe}.contact-status{background:#e9f4fd;color:#2879ae;border-radius:14px;font-size:11px}.import-panel{margin:20px}
@media(max-width:800px){.contact-actions{flex-wrap:wrap;padding:12px}.contact-search{order:3;width:100%;min-width:0}.contact-navigation{gap:16px;padding:0 12px}.contact-navigation button{font-size:11px}.contact-list-summary{padding:10px 12px}}
</style>
